"""Generate/check local notices from the audited distributed materials, offline.
Run from modern/scripts after integration; no dependency install or remote fetch.
"""
import hashlib, html, json, pathlib, sys
P=pathlib.Path(__file__).resolve().parents[1]
materials=[('Svelte','svelte','LICENSE.md','MIT'),('MessagePack','@msgpack/msgpack','LICENSE','ISC')]
sections=['<section aria-label="Project licence"><h2>Project licence</h2><p>Copyright © 2026 Aedan Lawrence. Original contributions to this frontend are licensed under GNU GPL version 3 or later. Third-party material retains its respective copyright and licence, as noted below. The combined application is distributed under GNU GPL version 3 because its SunRiser-derived material has no explicit later-version grant. Original contributions remain separately available under version 3 or later. The full GNU GPL version 3 text is included below.</p></section>'];sources=[]
for label,package,filename,license in materials:
 root=P/'node_modules'/package;meta=json.loads((root/'package.json').read_text());assert meta['license']==license
 path=root/filename;text=path.read_text();title=f'{label} {meta["version"]}'
 sections.append(f'<section aria-label="{html.escape(title)}"><h2>{html.escape(title)}</h2><p>{license} · bundled runtime code.</p><details><summary>Read {html.escape(title)} license</summary><pre>{html.escape(text)}</pre></details></section>')
 sources.append({'package':package,'version':meta['version'],'license':license,'license_file':str(path.relative_to(P)),'sha256':hashlib.sha256(path.read_bytes()).hexdigest()})
path=P/'LICENSE';text=path.read_text()
sections.append('<section aria-label="SunRiser legacy-derived material"><h2>SunRiser legacy-derived material</h2><p>Channel preset definitions, timezone choices, bundled recovery examples and adapted controller workflows originate from the SunRiser project. The original project declares its code and configuration under GNU GPL version 3, without an explicit later-version grant. Its other material, such as graphics, is CC BY 4.0 unless otherwise stated; the independently sourced font and photograph below retain their own licences. Adapted in 2026, this modern frontend changes their presentation and interaction; the corresponding modified frontend sources accompany this repository. Any included vendor firmware components retain their vendor and third-party terms; this frontend licence does not relicense the firmware. See the project packaging documentation for the included version.</p><p>Original attribution includes Torsten Raudssus and the SunRiser project. <a href="https://github.com/LEDaquaristik/sunriser" target="_blank" rel="noopener noreferrer">Original project source (external)</a></p><details><summary>Read GNU GPL version 3</summary><pre>'+html.escape(text)+'</pre></details></section>')
sources.append({'material':'SunRiser derived code/configuration','license':'GPL-3.0-only','license_file':'LICENSE','sha256':hashlib.sha256(path.read_bytes()).hexdigest()})
# Local artwork/photography have their own licences, separate from application GPL code.
font=P/'assets/fonts/OFL-Manrope.txt';text=font.read_text()
sections.append('<section aria-label="Manrope font"><h2>Manrope font</h2><p>Copyright 2018 The Manrope Project Authors (https://github.com/googlefonts/manrope). SIL Open Font License 1.1. The approved variable TTF is losslessly repackaged as inline WOFF2; no remote font service or extra font request.</p><details><summary>Read Manrope licence</summary><pre>'+html.escape(text)+'</pre></details></section>')
photo=json.loads((P/'assets/photo/manifest.json').read_text());original=photo['original'];credit=(P/'assets/photo/ATTRIBUTION.txt').read_text();legal=(P/'assets/photo/CC-BY-SA-3.0.txt').read_text()
# Retain the exact full licence document offline in an inert details frame-free text block.
sections.append('<section id="photography" aria-label="Aquarium photograph"><h2>Aquarium photograph</h2><p>'+html.escape(original['title'])+' — '+html.escape(original['author'])+'. <a href="'+html.escape(original['source_page'])+'" target="_blank" rel="noopener noreferrer">Original source (external)</a> · <a href="https://creativecommons.org/licenses/by-sa/3.0/" target="_blank" rel="noopener noreferrer">CC BY-SA 3.0 Unported (external)</a>.</p><p>Commercial use and redistribution with the application are permitted under the image licence. Cropped, downsampled with Lanczos, metadata removed and recompressed to AVIF/WebP. No upscaling, extra sharpening or colour manipulation. Photograph adaptations remain CC BY-SA 3.0, separate from the application code licence; no endorsement is implied.</p><p>The original page retains a generic unreviewed Korean-Wikipedia import notice. The explicit own-work author release and file history were independently checked; no VRT approval is claimed. The image is a reference aquascape, not a live view or physical output prediction.</p><details><summary>Read supplied attribution</summary><pre>'+html.escape(credit)+'</pre></details><details><summary>Read complete archived image licence document</summary><pre>'+html.escape(legal)+'</pre></details></section>')
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SunRiser · Local third-party notices</title><style>:root{color-scheme:dark}*{box-sizing:border-box}body{overflow-wrap:anywhere;margin:0;background:#142f29;color:#edf0e4;font:16px/1.6 system-ui,sans-serif}main{max-width:1100px;padding:32px 24px;margin:auto}h1{font-size:28px;line-height:1.3}h2{font-size:20px;margin:0 0 12px}p{color:#bdcdbb}a{color:#e4c497;display:inline-block;min-height:44px;padding:8px 0}section{border-top:1px solid #41614f;padding:24px 0}summary{min-height:48px;padding:12px 0;cursor:pointer;font-weight:600}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:14px/1.6 ui-monospace,monospace;background:#1b3a30;padding:16px;border-radius:6px}a:focus-visible,summary:focus-visible{outline:3px solid #ecd3a5;outline-offset:3px}@media(max-width:500px){main{padding:20px 16px}h1{font-size:25px}}</style></head><body><main><a href="./#help">← SunRiser help</a><h1>Local third-party notices</h1><p>These notices are included with the static application. No external content is fetched by this page; external links open only when selected.</p>'''+''.join(sections)+'''<section><h2>Asset and build inventory</h2><p>The modern UI uses locally embedded Manrope (OFL), an inline SVG horizon mark and the locally bundled reference aquarium photograph credited above. No external fonts, icons, images or runtime services are fetched. The mark is local UI artwork using the SunRiser name; this does not assert ownership of the product brand.</p><p>Vite, TypeScript, the Svelte compiler and test tools run during development/build, not as application services. The bundle audit identifies Svelte and MessagePack runtime code. clsx and esm-env are pruned from this build. Legacy jQuery, Bootstrap, Font Awesome and other unused legacy libraries are not included in the modern distribution.</p></section></main></body></html>'''
page=page.replace(' \n','&#32;\n')
output=P/'public/notices.html'
if '--check' in sys.argv:
 if not output.exists() or output.read_text()!=page:raise SystemExit('Local notices differ from audited license sources; run python3 scripts/notices.py and review.')
 print('Local notices match audited license files.')
else:
 output.parent.mkdir(exist_ok=True);output.write_text(page);print(f'Wrote {output}')
if '--inventory' in sys.argv:print(json.dumps(sources,indent=2))
